// 微信数据审计 (已重构升级为异步任务队列与百分比进度条轮询模式)
let lastScannedLeads = [];
async function fetchWechatData() {
  const out = document.getElementById('wechat-out');
  out.textContent = '⏳ [异步队列已启动] 正在初始化本地数据库扫描任务...\n';
  document.getElementById('lark-sync-btn').style.display = 'none'; // 重置同步按钮

  try {
    const triggerRes = await fetch(`${GATEWAY_URL}/api/wechat/openclaw/messages?async=true`);
    const triggerData = await triggerRes.json();
    if (!triggerData.success || !triggerData.task_id) {
      out.textContent = '❌ 初始化扫描任务失败。';
      return;
    }

    const taskId = triggerData.task_id;
    out.textContent += `🔑 任务已派发，ID: ${taskId}\n`;

    const pollInterval = setInterval(async () => {
      try {
        const statusRes = await fetch(`${GATEWAY_URL}/api/system/task/status?task_id=${taskId}`);
        const statusData = await statusRes.json();

        if (statusData.success) {
          out.textContent = `⏳ 正在解密本地 SQLite 并匹配 BANT 意向数据...\n` +
            `[进度]: ${statusData.progress}%\n`;

          if (statusData.status === 'completed') {
            clearInterval(pollInterval);
            const data = statusData.result;
            lastScannedLeads = data;
            document.getElementById('lark-sync-btn').style.display = 'block'; // 激活同步飞书按钮

            out.innerHTML = `<span style="color: var(--success-color);">✅ [扫描成功] 数据 100% 离线检索完毕！共发现 ${data.length} 条线索：</span><br>` + 
              data.map((m, i) => `${i+1}. <strong>${m.from_user}</strong>: "${m.content.substring(0,25)}..."`).join('<br>');
          }
        }
      } catch (pollErr) {
        clearInterval(pollInterval);
        out.textContent += `\n❌ 轮询进度失败: ${pollErr.message}`;
      }
    }, 500);

  } catch (err) {
    out.textContent = `[错误] 本地网关未响应。请确认终端已运行 npm start 启动 8888 端口。\n${err.message}`;
  }
}

// 物理同步数据至飞书多维表格
async function syncToLarkBitable() {
  const out = document.getElementById('wechat-out');
  out.innerHTML += `<br><br><span style="color: #38bdf8;">⏳ 正在调取飞书网关，推送线索至多维表格...</span>`;

  try {
    const res = await fetch(`${GATEWAY_URL}/api/lark/bitable/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ leads: lastScannedLeads })
    });
    const data = await res.json();

    if (data.success) {
      out.innerHTML += `<br><br><span style="color: var(--success-color);">🎉 [同步成功] ${data.message}</span><br>` +
        `🔗 <a href="${data.bitable_url}" target="_blank" style="color: #38bdf8; text-decoration: underline; font-weight: bold;">[点击此处直达您的飞书多维表格]</a>`;
    } else {
      out.innerHTML += `<br><span style="color: var(--danger-color);">❌ 同步飞书失败: ${data.error}</span>`;
    }
  } catch (err) {
    out.innerHTML += `<br><span style="color: var(--danger-color);">❌ 飞书网关连接失败: ${err.message}</span>`;
  }
}

